import i18n from "i18next";
import { initReactI18next } from "react-i18next";
import LanguageDetector from 'i18next-browser-languagedetector';

export const supportLanguages = [
    { "lang": "ar", "label": "العربية" },
    { "lang": "cs", "label": "čeština" },
    { "lang": "da", "label": "Dansk" },
    { "lang": "de", "label": "Deutsch" },
    { "lang": "el", "label": "Ελληνικά" },
    { "lang": "en", "label": "English" },
    { "lang": "en_US", "label": "English (US)" },
    { "lang": "en_GB", "label": "English (UK)" },
    { "lang": "en_AU", "label": "English (Australia)" },
    { "lang": "es", "label": "Español" },
    { "lang": "es_419", "label": "Español (Latinoamérica y Caribe)" },
    { "lang": "fi", "label": "Suomi" },
    { "lang": "fr", "label": "Français" },
    { "lang": "he", "label": "עִבְרִית" },
    { "lang": "hi", "label": "हिन्दी" },
    { "lang": "hr", "label": "Hrvatski" },
    { "lang": "hu", "label": "Magyar" },
    { "lang": "id", "label": "Bahasa Indonesia" },
    { "lang": "it", "label": "Italiano" },
    { "lang": "ja", "label": "日本語" },
    { "lang": "ko", "label": "한국어" },
    { "lang": "nl", "label": "Nederlands" },
    { "lang": "no", "label": "Norsk" },
    { "lang": "pl", "label": "Polski" },
    { "lang": "pt", "label": "Português" },
    { "lang": "pt_BR", "label": "Português (Brasil)" },
    { "lang": "pt_PT", "label": "Português (Portugal)" },
    { "lang": "ru", "label": "Русский" },
    { "lang": "sl", "label": "Slovenski" },
    { "lang": "sv", "label": "Svenska" },
    { "lang": "th", "label": "ไทย" },
    { "lang": "tr", "label": "Türkçe" },
    { "lang": "uk", "label": "Українська" },
    { "lang": "vi", "label": "Tiếng Việt" },
    { "lang": "zh_CN", "label": "简体中文" },
    { "lang": "zh_TW", "label": "繁體中文" },
];



export const getBrowserLanguage = () => {
    const lang = (navigator.language || navigator.userLanguage).replace("-", "_");
    return supportLanguages.some(l => l.lang === lang) ? lang : 'en';
};

const loadLanguageFiles = () => {
    const context = require.context("../_locales", true, /\.json$/);
    const resources = {};

    context.keys().forEach((key) => {
        const match = key.match(/\/([a-z]+_?[a-z]+)\/([a-z]+)\.json$/i);
        if (match) {
            const [, lang, namespace] = match;
            const normalizedLang = lang.replace("-", "_");
            if (!resources[normalizedLang]) resources[normalizedLang] = {};
            resources[normalizedLang][namespace] = context(key);
        }
    });

    return resources;
};
export const lng = getBrowserLanguage();
const resources = loadLanguageFiles();
export const namespaces = ['messages', 'options', 'translation'];
i18n
    .use(LanguageDetector)
    .use(initReactI18next)
    .init({
        resources,
        lng: lng,
        fallbackLng: "en",
        ns: namespaces,
        defaultNS: 'translation',
        debug: process.env.NODE_ENV === 'development',
        interpolation: {
            escapeValue: false,
        },
        detection: {
            order: ['querystring', 'navigator'],
            lookupQuerystring: 'lng',
        },
    });


export default i18n;