import { immer } from "zustand/middleware/immer";
import { userPublicLocalStorage } from "../user";
import { shallow } from 'zustand/shallow';
import { createWithEqualityFn } from 'zustand/traditional';
import { subscribeWithSelector } from 'zustand/middleware';
import { sendRuntimeMessage } from "../browers/runtime";
import { recordDebugLog } from "../../utils/helpers";
/*eslint no-return-await: "error"*/
export const localCacheSiteInstance = async () => {
    return userPublicLocalStorage('sites')
};

export const siteStore = createWithEqualityFn(subscribeWithSelector(immer((set, get) => ({
    sites: [],
    searchText: "",
    loadSiteConfigs: async () => {
        const cacheInstance = await localCacheSiteInstance();
        const savedSites = await cacheInstance.all();
        set({ sites: savedSites });
    },
    getSiteConfig: async (hostname) => {
        if (!hostname) return;
        if (!get().sites.length) {
            await get().loadSiteConfigs();
        }
        const site = get().sites.find(site => site.hostname === hostname);
        if (site) {
            return site;
        } else {
            const cacheInstance = await localCacheSiteInstance();
            return cacheInstance.get(`site_config_${hostname}`);
        }
    },
    setSiteConfig: async (hostname, config) => {
        if (!hostname) {
            console.warn('setSiteConfig hostname is null');
            return;
        }
        if (!config) {
            console.warn('setSiteConfig config is null');
            return;
        }

        const newConfig = {
            ...config,
            hostname,
            ...(config.urls && { urls: [...config.urls] })
        };

        set((state) => {
            const targetIndex = state.sites.findIndex(d => d.hostname === hostname);
            if (targetIndex !== -1) {
                const updatedSites = [...state.sites];
                updatedSites[targetIndex] = newConfig;
                return { sites: updatedSites };
            } else {
                return { sites: [...state.sites, newConfig] };
            }
        });

        await setCachedSiteConfig(hostname, newConfig);
        sendRuntimeMessage('run_sync', { data_type: 'siteConfigs' });
    },
    deleteSiteConfig: async (hostname) => {
        set({ sites: get().sites.filter(d => d.hostname !== hostname) });
        const cacheInstance = await localCacheSiteInstance();
        await cacheInstance.remove(`site_config_${hostname}`);
        sendRuntimeMessage('run_sync', { data_type: 'siteConfigs' });

    },
    restoreSiteConfigs: async (sites) => {
        if (!Array.isArray(sites)) {
            recordDebugLog("restoreSiteConfigs error: sites is not an array", sites);
            return;
        }

        try {
            const cacheInstance = await localCacheSiteInstance();
            await cacheInstance.clear();

            const promises = sites.map(async (config) => {
                if (!config.hostname) {
                    recordDebugLog("restoreSiteConfigs error: hostname missing in config", config);
                    return;
                }
                await setCachedSiteConfig(config.hostname, config);
            });

            await Promise.all(promises);
            set({ sites });
        } catch (error) {
            recordDebugLog("restoreSiteConfigs error", error, sites);
        }
    },

}
)
)), shallow)


export const getCachedSiteConfig = async (hostname) => {
    if (!hostname) return null;
    const cacheInstance = await localCacheSiteInstance();
    const cacheKey = `site_config_${hostname}`;
    return cacheInstance.get(cacheKey);
}

export const setCachedSiteConfig = async (hostname, config) => {
    if (!hostname || !config) {
        console.warn(`setSiteConfig ${!hostname ? 'hostname' : 'config'} is null`);
        return;
    }

    const cacheInstance = await localCacheSiteInstance();
    const cacheKey = `site_config_${hostname}`;
    const cache = await cacheInstance.get(cacheKey);

    const mergedConfig = {
        ...cache,
        ...config,
        hostname,
        ...(config.urls && { urls: [...config.urls] })
    };

    await cacheInstance.set(cacheKey, mergedConfig);
}

