import { faviconURL, isValidUrl } from "../../utils/helpers";
import { debounce, delay } from "lodash-es";
import chromeStorage from "../../utils/chromeStorage";
import { getTabMetadataCacheKey, setTabMetaCache, tabStore } from "../stores/tabStore";
import { userStore } from "../stores/userStore";
import { availableColors } from "../../utils/colors";
import { getUserConfig } from "../user";
import { siteStore } from "../stores/siteStore";
import { sendTabMessage } from "./runtime";

export async function getActiveTab() {
    const [activeTab] = await chrome.tabs.query({ active: true, url: ["http://*/*", "https://*/*"] });
    return activeTab;
}

export const getActiveTabUrl = async () => {
    const tab = await getActiveTab();
    return tab?.url;
}

export const setTabActive = async (tabId, tab) => {
    try {
        await chromeStorage('session').set('setLockActiveTabId', tabId);

        if (!tab) {
            tab = await chrome.tabs.get(tabId);
        }
        const tabWindow = await chrome.windows.get(tab.windowId);
        if (!tabWindow.focused) {
            await chrome.windows.update(tab.windowId, { drawAttention: true, focused: true });
            tabStore.setState({ activeWindowId: tab.windowId });
        }
        if (tab.discarded) {
            if (tab.active) {
                await chrome.tabs.reload(tabId);
            } else {
                await chrome.tabs.update(tab.id, { active: true });
            }
            return;
        }
        if (tab.active && tab.highlighted) {
            tabStore.getState().activeTab(tab.id);
            return true;
        }
        await chrome.tabs.highlight({ tabs: tab.index, windowId: tab.windowId });

        if (tab.groupId > -1) {
            const groupInfo = await chrome.tabGroups?.get(tab.groupId);
            if (groupInfo?.collapsed) {
                await chrome.tabGroups?.update(tab.groupId, { collapsed: false });
            }
        }
        return true;
    } catch (error) {
        console.error("setTabActive error", error);
        throw error;
    } finally {
        setTimeout(() => {
            chromeStorage('session').remove('setLockActiveTabId', tabId);
        }, 200);
    }
}

export async function getCurrentTab() {
    const [tab] = await chrome.tabs.query({ active: true, lastFocusedWindow: true });
    return tab;
}

export const removeTabById = async (tabId) => {
    await addTabRemoveList(tabId);
    try {
        await chrome.tabs.remove(tabId);
        tabStore.getState().closeTab();
    } catch (error) {
        console.error('removeTabById error', { tabId, error: error.message });
    } finally {
        delay(reduceTabRemoveList, 5000, tabId);
    }
}

const tabRemoveListCache = new Set();

export const addTabRemoveList = async (tabId) => {
    tabRemoveListCache.add(tabId);
    const cache = (await chromeStorage('session').get('tabRemoveList')) || [];
    await chromeStorage('session').set('tabRemoveList', [...cache, tabId]);
}

export const isTabInRemoveList = async (tabId) => {
    if (tabRemoveListCache.has(tabId)) {
        return true;
    }
    const removeList = (await chromeStorage('session').get('tabRemoveList')) || [];
    removeList.forEach(id => tabRemoveListCache.add(id));
    return tabRemoveListCache.has(tabId);
}

export const reduceTabRemoveList = async (tabId) => {
    tabRemoveListCache.delete(tabId);
    const cache = (await chromeStorage('session').get('tabRemoveList')) || [];
    await chromeStorage('session').set('tabRemoveList', cache.filter(id => id !== tabId));
}

export const formatTabData = (tab) => {
    const tabConfig = { ...tab };
    tabConfig.url = tab.pendingUrl || tab.url;

    const parseUrl = (url) => {
        try {
            const parsedUrl = new URL(url);
            return { hostname: parsedUrl.hostname, origin: parsedUrl.origin };
        } catch {
            // console.error(`parseUrl ${url} error`, e);
            return { hostname: url, origin: url };
        }
    };

    const { hostname, origin } = parseUrl(tabConfig.url);
    return {
        ...tabConfig,
        hostname,
        origin,
        tabId: tab.id,
        title: tab?.title.substring(0, 200),
        color: availableColors[tab.id % availableColors.length]
    };
}

export const sendMessageToAllTabs = async (action, data = {}) => {
    const queryOptions = {
        windowType: "normal",
        url: ["http://*/*", "https://*/*"],
        ...(data.windowId !== undefined && { windowId: data.windowId })
    };
    const tabs = await chrome.tabs.query(queryOptions);
    await Promise.all(tabs.map(tab => sendTabMessage(tab.id, action, data)));
}

export const handleThumbnailCreation = async (tabId) => {
    try {
        const { tabPreviewEnable, tabPreviewImage } = userStore.getState().settings;
        if (!tabPreviewEnable || !tabPreviewImage) {
            return null;
        }

        const checkTab = await chrome.tabs.get(tabId);
        if (!checkTab.active ||
            (checkTab.status !== "complete" && checkTab.active && !checkTab.discarded) ||
            !isValidUrl(checkTab.url)) {
            return null;
        }

        const tabWindow = await chrome.windows.get(checkTab.windowId, { populate: true });
        if (!tabWindow.focused) {
            return null;
        }

        const activeTab = tabWindow.tabs.find(tab => tab.active);
        if (activeTab.id !== checkTab.id) {
            return null;
        }

        return await chrome.tabs.captureVisibleTab(checkTab.windowId, { format: "jpeg", quality: 50 });
    } catch (error) {
        console.error("handleThumbnailCreation operation failed:", error);
        return null;
    }
}

export const playingVideoSwitchPip = async (tabId, type, action) => {
    const settings = await getUserConfig('user_settings');
    if (!settings) return false;

    if ((type === 'tab' && !settings.tabSwitchPip) ||
        (type === 'scroll' && !settings.scrollSwitchPip)) {
        return false;
    }

    const tabPipSupport = await getTabMetadataCacheKey(tabId, 'pipSupport');
    if (!tabPipSupport) return false;

    try {
        const tab = await chrome.tabs.get(tabId);
        const domainConfig = await siteStore.getState().getSiteConfig(new URL(tab.url).hostname);
        if (domainConfig?.tabSwitchPip === false) return false;

        await sendTabMessage(tabId, action);
    } catch (error) {
        console.error('playing_video_switch_pip error', error);
    }
}

export const saveTabPictureInPictureInfo = async (tabId, frameId, data) => {
    let pipMap = await getTabMetadataCacheKey(tabId, 'pipMap');
    if (!pipMap && frameId === 0) {
        pipMap = {};
    }

    await setTabMetaCache(tabId, 'pipMap', { ...pipMap, [frameId]: data });
    const [pipSupport, pipOn] = await Promise.all([
        checkPipInfo(tabId, 'pipSupport'),
        checkPipInfo(tabId, 'pipOn')
    ]);

    await Promise.all([
        setTabMetaCache(tabId, 'pipSupport', pipSupport),
        setTabMetaCache(tabId, 'pipOn', pipOn)
    ]);

    return { pipMap, pipSupport, pipOn };
}

const checkPipInfo = async (tabId, key) => {
    const pipMap = await getTabMetadataCacheKey(tabId, 'pipMap');
    if (!pipMap) return false;

    return Object.values(pipMap).some(frame => frame[key]);
}

export const updateTabHistory = debounce(async (tabId, tab) => {
    if (!tab?.url || !tabId) {
        return null;
    }

    try {
        const [urlHistories = [], navigationState = {}] = await Promise.all([
            getTabMetadataCacheKey(tabId, 'urlHistories'),
            getTabMetadataCacheKey(tabId, 'navigationState')
        ]);

        // Ensure urlHistories is an array
        const histories = Array.isArray(urlHistories) ? urlHistories : [];
        const currentIndex = navigationState?.currentHistoryIndex ?? -1;
        const currentUrl = currentIndex >= 0 && histories[currentIndex] ? histories[currentIndex].url : null;

        // Check navigation type
        const isRefresh = currentUrl === tab.url;
        const backIndex = currentIndex > 0 ? currentIndex - 1 : -1;
        const forwardIndex = currentIndex < histories.length - 1 ? currentIndex + 1 : -1;
        const backUrl = backIndex >= 0 && histories[backIndex] ? histories[backIndex].url : null;
        const forwardUrl = forwardIndex >= 0 && histories[forwardIndex] ? histories[forwardIndex].url : null;
        const isBackForward = tab.url === backUrl || tab.url === forwardUrl;

        const newUrlEntry = {
            tabId: tab.id,
            title: tab.title || '',
            url: tab.url,
            favIconUrl: tab?.favIconUrl || faviconURL(tab.url),
            lastAccessed: Date.now(),
            createdAt: Date.now(),
            visitCount: 1
        };

        let updatedHistories = [...histories];
        let newIndex = currentIndex;

        if (isRefresh && currentIndex >= 0 && updatedHistories[currentIndex]) {
            updatedHistories[currentIndex] = {
                ...updatedHistories[currentIndex],
                title: tab.title || updatedHistories[currentIndex].title,
                lastAccessed: Date.now(),
                visitCount: (updatedHistories[currentIndex].visitCount || 0) + 1
            };
        } else {
            const existingIndex = isBackForward ?
                updatedHistories.findIndex(entry => entry?.url === tab.url) :
                updatedHistories.findIndex(entry => entry?.url === tab.url);

            if (existingIndex !== -1) {
                newIndex = existingIndex;
                updatedHistories[existingIndex] = {
                    ...updatedHistories[existingIndex],
                    title: tab.title || updatedHistories[existingIndex].title,
                    lastAccessed: Date.now(),
                    visitCount: (updatedHistories[existingIndex].visitCount || 0) + 1
                };
            } else {
                newIndex = currentIndex + 1;
                updatedHistories.push(newUrlEntry);
            }
        }

        // Limit history size and mark active state
        const MAX_HISTORY = 50;
        if (updatedHistories.length > MAX_HISTORY) {
            const excess = updatedHistories.length - MAX_HISTORY;
            updatedHistories = updatedHistories.slice(excess);
            newIndex = Math.max(0, newIndex - excess);
        }

        // Filter out any null/undefined entries and update active states
        updatedHistories = updatedHistories
            .filter(Boolean)
            .map((entry, index) => ({
                ...entry,
                active: index === newIndex
            }));

        const newNavigationState = {
            currentHistoryIndex: newIndex,
            backUrl: newIndex > 0 && updatedHistories[newIndex - 1] ? updatedHistories[newIndex - 1].url : null,
            forwardUrl: newIndex < updatedHistories.length - 1 && updatedHistories[newIndex + 1] ? updatedHistories[newIndex + 1].url : null,
            canGoBack: newIndex > 0,
            canGoForward: newIndex < updatedHistories.length - 1
        };

        await Promise.all([
            tabStore.getState().setTabConfig(tabId, { urlHistories: updatedHistories, navigationState: newNavigationState }),
            setTabMetaCache(tabId, 'urlHistories', updatedHistories),
            setTabMetaCache(tabId, 'navigationState', newNavigationState)
        ]);

        return { urlHistories: updatedHistories, navigationState: newNavigationState };
    } catch (error) {
        console.error('Error updating tab history:', error);
        return null;
    }
}, 500);