import localCache from "../utils/localCache";
import chromeStorage from "../utils/chromeStorage";
import { decryptDataWithPassword, encryptDataWithPassword, sha256 } from "../utils/crypto";
import { memoryStore } from "../utils/memoryStore";
import { isString } from "lodash-es";
import { sendRuntimeMessage } from "./browers/runtime";
import { sendMessageToAllTabs } from "./browers/tabs";
import { recordDebugLog } from "../utils/helpers";

const chromeStorageLocal = chromeStorage("local");
const chromeStorageSync = chromeStorage("sync");



export const setUserConfig = async (key, config) => {
    console.log("setUserConfig", key, config);
    return chromeStorageLocal.set(key, config);
}

export const getUserConfig = async (key) => {
    const config = await chromeStorageLocal.get(key);
    return config;
}

export const getSettingByKey = async (key) => {
    const settings = await getUserConfig('user_settings') || {};
    return settings[key];
}


export const deleteUserConfig = async (key) => {
    await chromeStorageLocal.remove(key);
    console.log("deleteUserConfig", key);
    return true;
}

/**
 * Sets the local password for the user.
 *
 * @param {string} password - The password to be set.
 * @return {Promise<void>} - A promise that resolves when the password is set.
 */
export const setLocalPassword = async (password) => {
    const hashedPassword = await sha256(password);
    await chromeStorageSync.set('user-local-password', hashedPassword);
    memoryStore.delete('user-local-password');
    await setUserConfig('local_password_set', true);
}

export const getLocalPassword = async () => {
    const cacheLocalPwd = memoryStore.get('user-local-password');
    if (cacheLocalPwd) return cacheLocalPwd;
    const localPassword = await chromeStorageSync.get('user-local-password') || await sha256('vertitab');
    memoryStore.set('user-local-password');
    return localPassword;
}

export const hasLocalPassword = async () => {
    return !! await getUserConfig('local_password_set');
}

/**
 * Checks if the provided password matches the locally stored password.
 *
 * @param {string} password - The password to be checked.
 * @return {Promise<boolean>} A promise that resolves to true if the password matches, false otherwise.
 */
export const checkLocalPassword = async (password) => {
    const localPassword = await getLocalPassword();
    if (localPassword) {
        const hashedPassword = await sha256(password);
        return hashedPassword === localPassword;
    }
    return false;
}



export const encryptData = async (data, password) => {
    const localPassword = password || (await getLocalPassword());
    const rawStr = isString(data) ? data : JSON.stringify(data);
    return encryptDataWithPassword(localPassword, rawStr);
}

export const decryptData = async (encryptedString, password) => {
    if (!encryptedString) return null;
    const localPassword = password || (await getLocalPassword());
    const decryptedStr = await decryptDataWithPassword(localPassword, encryptedString);
    return JSON.parse(decryptedStr);
}

let uuidPromise = null;

export const getCurrentUserUUID = async () => {
    if (uuidPromise) return uuidPromise;

    uuidPromise = (async () => {
        let uuid = memoryStore.get('rabbitpair_active_user_uuid');
        if (uuid) return uuid;

        uuid = await chromeStorageLocal.get('rabbitpair_active_user_uuid');
        if (uuid) {
            memoryStore.set('rabbitpair_active_user_uuid', uuid);
            return uuid;
        }

        uuid = crypto.randomUUID();
        await chromeStorageLocal.set('rabbitpair_active_user_uuid', uuid);
        memoryStore.set('rabbitpair_active_user_uuid', uuid);
        return uuid;
    })();

    return uuidPromise;
};

export const setAccessToken = async (accessToken) => {
    await chromeStorageSync.set('rabbitpair_access_token', accessToken);
    memoryStore.set('rabbitpair_access_token', accessToken);
    return accessToken;
}

export const getAccessToken = async () => {
    let accessToken = memoryStore.get('rabbitpair_access_token');
    if (accessToken) return accessToken;
    accessToken = await chromeStorageSync.get('rabbitpair_access_token');
    if (accessToken) {
        memoryStore.set('rabbitpair_access_token', accessToken);
    }
    return accessToken;
}
export const removeAccessToken = async () => {
    await chromeStorageSync.remove('rabbitpair_access_token');
    memoryStore.remove('rabbitpair_access_token');
    return null;
}

export const setUserInfo = async (userInfo) => {
    const userUUID = await getCurrentUserUUID();
    await setUserConfig('rabbitpair_user_info', await encryptData(userInfo, userUUID));
    await setUserConfig('rabbitpair_is_user_logged_in', true);
    await sendRuntimeMessage("user_logged_in", { user: userInfo });
    const result = userInfo;
    setTimeout(async () => {
        await sendMessageToAllTabs('refresh_setting');
    }, 3000);
    return result;
}

export const getUserInfo = async () => {
    let userInfo = await getUserConfig('rabbitpair_user_info');
    const userUUID = await getCurrentUserUUID();
    const decryptUserInfo = await decryptData(userInfo, userUUID);
    return decryptUserInfo;
}
export const removeUserInfo = async () => {
    await deleteUserConfig('rabbitpair_user_info');
    await deleteUserConfig('rabbitpair_is_user_logged_in');
    await sendRuntimeMessage("user_logged_out");
    setTimeout(async () => {
        await sendMessageToAllTabs('refresh_setting');
    }, 3000);
    return null;
}
/*eslint no-return-await: "error"*/
export const userPublicLocalStorage = async (namespace = 'stored') => {
    const cacheKey = 'userPublicLocalStorage' + namespace;
    let store = memoryStore.get(cacheKey);
    if (store) return store;

    const userUUID = await getCurrentUserUUID();
    store = localCache('users/' + userUUID + '/public/' + namespace);
    memoryStore.set(cacheKey, store);
    return store;
}

export const userEncryptLocalStorage = async () => {
    const userUUID = await getCurrentUserUUID();
    return localCache('users/' + userUUID + '/encrypted');
}

export const generateSessionKey = async (sessionId, namespace = 'stored') => {
    const userUUID = await getCurrentUserUUID();
    return `users/${userUUID}/${namespace}/${sessionId}`;
}

export const saveEncryptData = async (key, data) => {
    const localCacheEncryptInstance = await userEncryptLocalStorage();
    const encryptedData = await encryptData(data);
    await localCacheEncryptInstance.set(key, encryptedData);
    memoryStore.set(key, data);
}

export const getEncryptData = async (key) => {
    let data = memoryStore.get(key);
    if (data) return data;

    const localCacheEncryptInstance = await userEncryptLocalStorage();
    const encryptedData = await localCacheEncryptInstance.get(key);
    data = await decryptData(encryptedData);
    memoryStore.set(key, data);
    return data;
}

const isWithin24Hours = (install_at) => {
    if (!install_at) return false;
    const installDate = new Date(install_at);
    const now = new Date();
    return (now - installDate) <= 24 * 60 * 60 * 1000; // 24 hours in milliseconds
};

export const checkIsMembership = async () => {
    const install_at = await getUserConfig("install_at");
    if (isWithin24Hours(install_at)) {
        return true;
    }
    const userinfo = await getUserInfo();
    return userinfo?.membership?.is_member === true;
}

export const getMembershipType = async () => {
    const install_at = await getUserConfig("install_at");
    const userinfo = await getUserInfo();
    const membershipType = userinfo?.membership?.type;
    const isTrial = isWithin24Hours(install_at);

    if (process.env.NODE_ENV !== 'production') {
        console.log('getMembershipType', {
            userinfo,
            membershipType,
            isWithin24Hours: isTrial,
            result: membershipType || (isTrial ? "trial" : "free")
        });
    }

    return membershipType || (isTrial ? "trial" : "free");
}

export const fetchUserInfo = async () => {
    try {

        const [uuid, accessToken, extension] = await Promise.all([getCurrentUserUUID(), getAccessToken(), chrome.management.getSelf()]);
        if (!accessToken) {
            return null
        }

        const response = await fetch(`${process.env.BASE_API}/api/v1/user/info`, {
            method: 'GET',
            headers: {
                'Authorization': `Bearer ${accessToken}`,
                'X-Device-Id': uuid,
                'X-Extension-Id': chrome.runtime.id,
                'X-Extension-Version': extension.version,
                'X-Extension-InstallType': extension.installType,
            },
        });
        let responseJSON = await response.json();
        recordDebugLog("fetchUserInfo responseJSON", responseJSON);
        if (responseJSON?.code === 0) {
            await setUserInfo(responseJSON.data);
            return responseJSON.data;
        }
        return null;
    } catch (error) {
        console.error('Error fetching user info:', error);
        return { code: -1, error: 'Failed to fetch user info' };
    }
};

export const userLogout = async () => {
    try {

        const [uuid, accessToken, extension] = await Promise.all([getCurrentUserUUID(), getAccessToken(), chrome.management.getSelf()]);
        if (!accessToken) {
            return true;
        }
        const response = await fetch(`${process.env.BASE_API}/api/v1/auth/logout`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${accessToken}`,
                'X-Device-Id': uuid,
                'X-Extension-Id': chrome.runtime.id,
                'X-Extension-Version': extension.version,
                'X-Extension-InstallType': extension.installType,
            },
        });

        const responseJson = await response.json();
        console.debug("userLogout response", responseJson);

        if (responseJson.code !== 0) {
            console.warn("Unexpected response code during logout:", responseJson.code);
            return false;
        }

        return true;
    } catch (error) {
        console.error('API logout error:', error);
        return false;
    } finally {
        // Always remove tokens to ensure user is logged out locally
        await removeAccessToken()
        await removeUserInfo()
    }
}
